INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa77d-8469-7104-aa43-56df5a5cb8fe'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Prime factorisation, HCF and LCM', 'Express numbers as products of primes in index form, then read HCF from shared primes at lowest powers and LCM from every prime at highest powers.', ARRAY['A prime is greater than 1 and divisible only by itself and 1', 'HCF: common bases only, take the lowest power of each', 'LCM: every prime that appears, take the highest power of each', 'For a perfect square (cube), every prime power in the factorisation must be divisible by 2 (3)']::text[], ARRAY['{"note":"Ignore primes that appear in only one number.","label":"HCF from primes","expression":"HCF = product of shared primes at lowest powers"}'::jsonb, '{"note":"Include primes found in only one of the numbers.","label":"LCM from primes","expression":"LCM = product of all primes at highest powers"}'::jsonb]::text[], ARRAY['{"steps":["560 = 2^4 x 5 x 7 and 168 = 2^3 x 3 x 7","Shared primes: 2 and 7","Lowest powers: 2^3 and 7","HCF = 2^3 x 7 = 56"],"answer":"56","question":"Find the HCF of 168 and 560."}'::jsonb, '{"steps":["2700 = 2^2 x 3^3 x 5^2","For a square, every power must be divisible by 2; only 3^3 needs one more factor of 3, so h = 3","For a cube, every power must be divisible by 3; need 2^1 and 5^1 more, so k = 2 x 5 = 10"],"answer":"2700 = 2^2 x 3^3 x 5^2; h = 3; k = 10","question":"Express 2700 as a product of primes. Find the smallest h so that 2700h is a perfect square, and the smallest k so that 2700k is a perfect cube."}'::jsonb]::text[], ARRAY['{"fix":"HCF uses the lowest shared powers. Highest powers are for LCM.","mistake":"Taking the highest powers when finding the HCF."}'::jsonb, '{"fix":"LCM must include every prime that appears in either number.","mistake":"Leaving out a prime that appears in only one number when finding the LCM."}'::jsonb]::text[], ARRAY['Write both numbers in index form before comparing primes.', 'For square/cube questions, check which powers are not divisible by 2 or 3, then multiply by the missing factors.']::text[], ARRAY['t04']::text[], 101, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:50:48.807Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa77d-846f-77df-b73d-aeca15ab2712'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Indices and standard form', 'Index laws let you simplify powers without expanding. Standard form keeps very large or small numbers as A x 10^n with 1 <= A < 10.', ARRAY['Same base: multiply by adding indices, divide by subtracting, and raise a power by multiplying indices', 'a^(-n) = 1/a^n and a^0 = 1 (a != 0)', 'Fractional indices are roots: a^(m/n) is the nth root of a^m', 'Standard form is A x 10^n where 1 <= A < 10']::text[], ARRAY['{"note":"Bases must match for the first two laws.","label":"Core index laws","expression":"a^m x a^n = a^(m+n); a^m / a^n = a^(m-n); (a^m)^n = a^(mn)"}'::jsonb, '{"note":"Neither law applies when a = 0.","label":"Negative and zero index","expression":"a^(-n) = 1/a^n; a^0 = 1"}'::jsonb, '{"note":"Also (ab)^n = a^n b^n and (a/b)^m = a^m / b^m.","label":"Fractional index","expression":"a^(m/n) = (nth root of a)^m"}'::jsonb]::text[], ARRAY['{"steps":["Apply (ab)^n = a^n b^n and a^(m/n) as a root: (4x^2)^(3/2) = 4^(3/2) x (x^2)^(3/2)","4^(3/2) = (sqrt(4))^3 = 2^3 = 8","(x^2)^(3/2) = x^(2 x 3/2) = x^3"],"answer":"8x^3","question":"Simplify (4x^2)^(3/2)."}'::jsonb, '{"steps":["8^0 = 1","(1/2)^(-4) = (2/1)^4 = 16","16 x 1 = 16"],"answer":"16","question":"Evaluate (1/2)^(-4) x 8^0."}'::jsonb]::text[], ARRAY['{"fix":"A negative index flips into a reciprocal; it does not change the sign.","mistake":"Treating a negative index as making the answer negative."}'::jsonb, '{"fix":"The first part must satisfy 1 <= A < 10, so write 3.4 x 10^6.","mistake":"Leaving standard form as 34 x 10^5."}'::jsonb]::text[], ARRAY['Rewrite nested roots and brackets fully in index form before simplifying from the inside out.', 'Spot zero powers early; they often collapse a messy expression to 1.']::text[], ARRAY['t04']::text[], 102, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:50:48.807Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa797-96d3-7fe3-9af0-0623a57032f0'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Significant figures, decimal places and estimation', 'Significant figures count from the first non-zero digit. Estimation checks whether an answer is a sensible size.', ARRAY['Count significant figures from the first non-zero digit onwards', 'Leading zeros are never significant, but trailing zeros after a decimal point are', 'Decimal places are counted from the decimal point, regardless of zeros', 'Keep full accuracy through the working and round only at the final step']::text[], ARRAY['{"note":"A quick way to confirm your exact answer is the right size.","label":"Estimation check","expression":"round each value to 1 significant figure, then calculate"}'::jsonb]::text[], ARRAY['{"steps":["0.0085: the leading zeros are not significant, so only the 8 and 5 count","20007: the zeros sit between non-zero digits, so all five digits count","12.000: trailing zeros after a decimal point are significant, so all five count"],"answer":"2, 5 and 5 significant figures","question":"State the number of significant figures in 0.0085, 20007 and 12.000."}'::jsonb]::text[], ARRAY['{"fix":"Start counting at the first non-zero digit, giving 2 significant figures.","mistake":"Counting the leading zeros in 0.0085 as significant figures."}'::jsonb, '{"fix":"Trailing zeros after a decimal point show the accuracy and must be kept.","mistake":"Dropping the trailing zeros when writing 12.000."}'::jsonb, '{"fix":"Keep the full value in your calculator and round only the final answer.","mistake":"Rounding partway through a multi-step calculation."}'::jsonb]::text[], ARRAY['Check whether the question asks for significant figures or decimal places, they are not the same.', 'If the question does not specify, give money to 2 decimal places and other answers to 3 significant figures.']::text[], ARRAY['t04']::text[], 103, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T07:19:17.458Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa77d-846f-7886-a96c-1af51559f12c'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'Ratio and proportional sharing', 'Ratios compare parts. Convert a ratio into total parts before sharing an amount.', ARRAY['Ratios have no units and should be simplified', 'Total parts = sum of all ratio numbers', 'One part = total amount divided by total parts']::text[], ARRAY['{"note":"Always find the value of one part first.","label":"Sharing in a ratio","expression":"share = (its part / total parts) x total amount"}'::jsonb]::text[], ARRAY['{"steps":["Let the numbers be x and 4x","After the change: (x - 5) and (4x + 10)","So (x - 5) / (4x + 10) = 1/6","6x - 30 = 4x + 10, so 2x = 40"],"answer":"20 yellow balls","question":"A bag has yellow and blue balls in the ratio 1:4. Five yellow are removed and 10 blue added, giving a new ratio 1:6. Find the original number of yellow balls."}'::jsonb]::text[], ARRAY['{"fix":"A ratio only gives proportions. Find the value of one part first.","mistake":"Treating a ratio number as the actual quantity."}'::jsonb, '{"fix":"Convert both quantities to the same unit, then simplify.","mistake":"Forgetting to simplify units before writing a ratio."}'::jsonb]::text[], ARRAY['Set unknowns as x and 4x rather than two separate letters.', 'Check your answer satisfies the original ratio.']::text[], ARRAY['t06']::text[], 201, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:50:48.807Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa77d-846f-78a5-8c08-d120beccd3ac'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'Direct and inverse proportion', 'Direct proportion means y = kx. Inverse proportion means y = k/x (or y = k over a power/root of x).', ARRAY['Direct: as one quantity increases, the other increases and y = bx for a constant b', 'Inverse: as one quantity increases, the other decreases and y = b/x', 'Find the constant from the given pair first, then substitute the new value']::text[], ARRAY['{"note":"b is the constant of proportionality.","label":"Direct proportion","expression":"y = bx"}'::jsonb, '{"note":"Also used with roots or powers, e.g. L = b / sqrt(M).","label":"Inverse proportion","expression":"y = b / x"}'::jsonb]::text[], ARRAY['{"steps":["y = bx so 144 = b(12), giving b = 12","When x = 7: y = 12 x 7 = 84"],"answer":"84","question":"y is directly proportional to x. Given y = 144 when x = 12, find y when x = 7."}'::jsonb, '{"steps":["L = b / sqrt(M)","35 = b / 10, so b = 350","700 = 350 / sqrt(M), so sqrt(M) = 1/2 and M = 1/4"],"answer":"M = 1/4","question":"L is inversely proportional to sqrt(M). When M = 100, L = 35. Find M when L = 700."}'::jsonb]::text[], ARRAY['{"fix":"Always substitute the given pair to find b before answering.","mistake":"Skipping the step of finding the constant."}'::jsonb, '{"fix":"Inverse means y = b/x (or b over the stated expression).","mistake":"Using y = bx when the question says inversely proportional."}'::jsonb]::text[], ARRAY['Underline whether the question says directly or inversely proportional.', 'Label given and new values clearly so the constant step is easy to check.']::text[], ARRAY['t05']::text[], 202, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:50:48.807Z'::timestamptz) ON CONFLICT (id) DO NOTHING;